    "audit_result": {
      "property_id": "PROP-57888860-pre-006",
      "classification": "vulnerability",
      "code_path": "beacon_chain/spec/peerdas_helpers.nim::assemble_data_column_sidecars::L328",
      "proof_trace": "Missing bounds check before array access. Function assumes cell_proofs.len >= blobs.len * CELLS_PER_EXT_BLOB but no validation exists at any call site (RPC, EL paths, block recovery). Proof fails because REST API and EL interfaces accept external/untrusted data without length validation.",
      "attack_scenario": "Attacker sends REST API request to /eth/v2/beacon/blocks with N blobs but fewer than N * CELLS_PER_EXT_BLOB proofs. Line 328 accesses cell_proofs[i * CELLS_PER_EXT_BLOB + j] out of bounds, causing IndexDefect and beacon node crash (DoS).",
      "checklist_id": "PROP-57888860-pre-006"
    },
    "text": "Proof slicing indices in cells_and_kzg_proofs_construction must always be within blobs_bundle.proofs bounds.",
    "assertion": "forall blob_i: start == i * CELLS_PER_EXT_BLOB AND end == (i+1) * CELLS_PER_EXT_BLOB AND end <= len(blobs_bundle.proofs)",
    "covers": "SG-002",
    "severity": "MEDIUM",
    "type": "pre-condition"
  }
}

